import { ADD, Del } from "../types";

const initalState = {
  task: [],
};

const deleteSelected = (payload) => {
  initalState.task.filter((elm) => {
    return elm.id !== payload;
  });
};

const taskReducer = (state = initalState, action) => {
  switch (action.type) {
    case ADD:
      return {
        task: [
          ...state.task,
          {
            id: new Date().getTime(),
            task: action.payload,
            date: `${new Date().getFullYear()} / ${
              new Date().getMonth() + 1
            } / ${new Date().getDay()}`,
            checked: false,
          },
        ],
      };
    case Del:
      return deleteSelected(action.payload);

    default:
      return state;
  }
};

export default taskReducer;
